/* ---------- property application ---------- */
function computeAll(t){
  var out={},k,tr;
  for(k=0;k<DATA.tracks.length;k++){
    tr=DATA.tracks[k];
    if(!out[tr.el])out[tr.el]={};
    out[tr.el][tr.p]=evalTrack(tr.k,t);
