}
function apply(){
  var all=computeAll(S.t),id;
  for(id in DATA.elements){applyElement(id,all[id]||{});}
}

/* ---------- segments ---------- */
function segTime(seg,elapsed){
  var span=Math.max(1,seg.end-seg.start),local,cycle;
  if(seg.loop){
    cycle=seg.direction==="yoyo"?span*2:span;
    local=((elapsed%cycle)+cycle)%cycle;
    if(seg.direction==="yoyo"&&local>span)local=2*span-local;
  }else{
    if(seg.direction==="yoyo"){cycle=span*2;var c=Math.max(0,Math.min(cycle,elapsed));local=c>span?2*span-c:c;}
    else local=Math.max(0,Math.min(span,elapsed));
  }
  if(seg.direction==="reverse")local=span-local;
  return seg.start+local;
}

/* ---------- playback ---------- */
var prevT=0;
function tick(now){
  if(S.destroyed)return;
  var dt=(now-S.last)*S.speed;
  S.last=now;
  prevT=S.t;
  if(S.seg){
    S.segElapsed+=dt;
    S.t=segTime(S.seg,S.segElapsed);
    if(!S.seg.loop&&S.segElapsed>=(S.seg.direction==="yoyo"?2:1)*(S.seg.end-S.seg.start)){S.playing=false;}
  }else{
    S.t+=dt;
    if(S.t>=DATA.duration){
      if(DATA.loop)S.t=S.t%DATA.duration;
      else{S.t=DATA.duration;S.playing=false;}
    }else if(S.t<0){
      if(DATA.loop)S.t=((S.t%DATA.duration)+DATA.duration)%DATA.duration;
      else{S.t=0;S.playing=false;S.speed=Math.abs(S.speed);}
    }
  }
  checkMarkers(prevT,S.t);
  apply();
  if(S.playing)S.raf=requestAnimationFrame(tick);
}
function startLoop(){
  if(!S.playing){S.playing=true;S.last=performance.now();S.raf=requestAnimationFrame(tick);}
}
function checkMarkers(a,b){
  if(!DATA.markerTriggers.length)return;
  var m,tr,j;
  for(j=0;j<DATA.markerTriggers.length;j++){
    tr=DATA.markerTriggers[j];
    m=tr.time;
    if((a<m&&b>=m)||(S.speed<0&&a>m&&b<=m))runAction(tr);
  }
}

/* ---------- actions ---------- */
function findSeg(idOrName){
  for(var j=0;j<DATA.segments.length;j++){
    if(DATA.segments[j].id===idOrName||DATA.segments[j].name===idOrName)return DATA.segments[j];
  }
  return null;
}
function runAction(b,progress){
  if(!motionAllowed&&b.action!=="pause"&&b.action!=="stop")return;
  if(b.mapProperty&&b.targetId&&progress!==undefined){
    var outMin=b.mapOutMin||0,outMax=b.mapOutMax===undefined?1:b.mapOutMax;
    if(!S.over[b.targetId])S.over[b.targetId]={};
    S.over[b.targetId][b.mapProperty]=outMin+(outMax-outMin)*progress;
    if(!S.playing)apply();
    return;
  }
  if(b.trigger==="scroll"&&b.scrollMode==="scrub"&&progress!==undefined){
    var pp=b.scrollReverse?1-progress:progress;
    pp=Math.max(0,Math.min(1,pp));
    var sseg=b.targetKind==="segment"?findSeg(b.targetId):null;
    S.playing=false;
    S.t=sseg?sseg.start+(sseg.end-sseg.start)*pp:DATA.duration*pp;
    apply();
    return;
  }
  if(b.trigger==="pointer-move"&&progress!==undefined&&!b.mapProperty){
    S.playing=false;S.t=DATA.duration*Math.max(0,Math.min(1,progress));apply();return;
  }
  switch(b.action){
    case"play":S.seg=null;startLoop();break;
    case"pause":S.playing=false;break;
    case"stop":S.playing=false;S.seg=null;S.t=0;apply();break;
    case"restart":S.seg=null;S.t=0;startLoop();break;
    case"reverse":S.speed=-Math.abs(S.speed||1);startLoop();break;
    case"seek":S.playing=false;S.t=Number(b.value)||0;apply();break;
    case"seek-marker":
      for(var j=0;j<DATA.markers.length;j++)if(DATA.markers[j].id===b.targetId){S.playing=false;S.t=DATA.markers[j].time;apply();}
      break;
    case"play-segment":
      var seg=findSeg(b.targetId);
      if(seg){S.seg=seg;S.segElapsed=0;S.t=seg.start;startLoop();}
      break;
    case"set-speed":S.speed=Number(b.value)||1;break;
    case"set-variable":
      for(var vj=0;vj<DATA.variables.length;vj++)if(DATA.variables[vj].id===b.targetId){S.inputs[DATA.variables[vj].name]=b.value;}
      if(!S.playing)apply();
      break;
    case"set-region-enabled":
      if(b.targetId){
        if(!S.over[b.targetId])S.over[b.targetId]={};
        var cur=S.over[b.targetId].regionAmount;
        S.over[b.targetId].regionAmount=(cur===undefined||Number(cur)>0)?0:1;
        if(!S.playing)apply();
      }
      break;
  }
}

/* ---------- triggers ---------- */
var listeners=[];
function on(target,type,fn,opts){target.addEventListener(type,fn,opts);listeners.push([target,type,fn]);}
function byTrigger(name){
  var out=[],j;
  for(j=0;j<DATA.triggers.length;j++)if(DATA.triggers[j].trigger===name)out.push(DATA.triggers[j]);
  return out;
}
function bindSimple(name,domEvent){
  var list=byTrigger(name);
  if(!list.length)return;
  on(svg,domEvent,function(){for(var j=0;j<list.length;j++)runAction(list[j]);});
}
bindSimple("hover-enter","pointerenter");
bindSimple("hover-leave","pointerleave");
bindSimple("click","click");
bindSimple("pointer-down","pointerdown");
bindSimple("pointer-up","pointerup");




/* ---------- public API ---------- */
var api={
  play:function(){runAction({action:"play"});},
  pause:function(){runAction({action:"pause"});},
  stop:function(){runAction({action:"stop"});},
  restart:function(){runAction({action:"restart"});},
  reverse:function(){runAction({action:"reverse"});},
  seek:function(ms){S.playing=false;S.seg=null;S.t=Math.max(0,Math.min(DATA.duration,Number(ms)||0));apply();},
  playSegment:function(name){var seg=findSeg(name);if(seg){S.seg=seg;S.segElapsed=0;S.t=seg.start;startLoop();}},
  setSpeed:function(v){S.speed=Number(v)||1;},
  setInput:function(name,value){S.inputs[name]=value;if(!S.playing)apply();},
  getTime:function(){return S.t;},
  getDuration:function(){return DATA.duration;},
  destroy:function(){
    S.destroyed=true;S.playing=false;
    if(S.raf)cancelAnimationFrame(S.raf);
    for(var j=0;j<listeners.length;j++){try{listeners[j][0].removeEventListener(listeners[j][1],listeners[j][2]);}catch(err){}}
    listeners.length=0;
    try{delete window.InkFlowInstances[P];}catch(err){}
  }
};
try{svg.inkflow=api;}catch(err){}
window.InkFlowInstances=window.InkFlowInstances||{};
window.InkFlowInstances[P]=api;
try{svg.dispatchEvent(new CustomEvent("inkflow:ready",{detail:api,bubbles:true}));}catch(err){}

/* ---------- boot ---------- */
apply();
if(reducedMotion&&DATA.reducedMotion==="final-frame"){S.t=DATA.duration;apply();}
else if(reducedMotion&&DATA.reducedMotion==="static"){S.t=0;apply();}
else{
  var autos=byTrigger("autoplay"),j2;
  if(DATA.autoplay&&!autos.length)startLoop();
  for(j2=0;j2<autos.length;j2++)runAction(autos[j2]);
}
})();
